import React from "react";

function Ancher({ text, url }) {
  return (
    <div className="flex justify-center mt-5 mb-5 hover:scale-125 ">
      <a
        href={url}
        target="_blank"
        rel="noopener noreferrer"
        className=" text-white bg-purple-950 rounded-md w-3/12 h-12 items-center flex justify-center "
      >
        {text}
      </a>
    </div>
  );
}

export default Ancher;
